# Database update impact analysis: Schema Field Rename Impact
graph = {"rename field customer_name": "42 queries; 3 indexes; 7 consumers".split(";")}
blast, frontier = set(), ["rename field customer_name"]
while frontier:
    n = frontier.pop()
    for m in graph.get(n, []):
        if m not in blast:
            blast.add(m); frontier.append(m)
print("change:", "rename field customer_name")
print("blast radius:", sorted(blast) or "none")
print("assessment:", "medium: contained to consumers")

